// Flat config. Each block says which files it applies to and why.
import js from '@eslint/js';
import lit from 'eslint-plugin-lit';
import globals from 'globals';
import tseslint from 'typescript-eslint';

export default [
  // Dependencies, and the generated API client (regenerated by npm run generate-client, never edited by hand).
  { ignores: ['**/node_modules/**', 'src/api/**'] },

  js.configs.recommended,

  // Backoffice sources run in the browser.
  { files: ['src/**/*.ts'], languageOptions: { globals: globals.browser } },

  // Node tooling: root config files and the client generator.
  { files: ['*.{js,ts}', 'scripts/**/*.js'], languageOptions: { globals: globals.node } },

  // TypeScript rules only where TypeScript lives.
  ...tseslint.configs.recommended.map((config) => ({ ...config, files: ['**/*.ts'] })),

  // Lit templates: bindings, attribute names, duplicate templates.
  { ...lit.configs['flat/recommended'], files: ['src/**/*.ts'] },
];
